import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';

// --- DashboardMenuButton (Modified to be the bell icon trigger) ---
// Now contains both the Bell and the Menu Button in the absolute position
const DashboardBellAndMenu = ({ onMenuClick, isEasyMode, t, toggleAlert, isAlertExpanded }) => ( 
    <div style={{ 
        position: 'absolute', 
        top: '10px', // Slightly lower from the very top edge
        right: '15px',
        zIndex: 100,
        display: 'flex',
        alignItems: 'center',
    }}>
        {/* 1. BLINKING BELL ICON (Toggles the alert) */}
        <button
            onClick={toggleAlert}
            style={{ 
                padding: '8px',
                backgroundColor: 'transparent', 
                border: 'none', 
                cursor: 'pointer',
                fontSize: isEasyMode ? '36px' : '28px', 
                color: isAlertExpanded ? '#FFC107' : '#E8F0FE', // Make it stand out when active
                textShadow: '0 0 5px rgba(255, 193, 7, 0.8)',
                animation: isAlertExpanded ? 'none' : 'blink-bell 1.5s infinite alternate', // Only blink when not expanded
                marginRight: '10px'
            }}
        >
            <span role="img" aria-label={t('general.alert')}>🔔</span>
        </button>

        {/* 2. MENU BUTTON */}
        <button
            onClick={onMenuClick}
            style={{ 
                padding: '8px',
                backgroundColor: 'transparent', 
                border: 'none', 
                cursor: 'pointer',
                fontSize: isEasyMode ? '36px' : '28px', 
                color: '#333',
                transition: 'color 0.2s',
            }}
            onMouseOver={e => e.currentTarget.style.color = '#1A73E8'} 
            onMouseOut={e => e.currentTarget.style.color = '#333'}
        >
            <span role="img" aria-label={t('general.menu')}>☰</span>
        </button>
    </div>
);
// --- END DashboardBellAndMenu ---


// --- Icon Component Modification (No changes) ---
const Icon = ({ name, emoji, isActive, onClick, isProminent, isEasyMode, keyName, color = '#1A73E8', bgColor = '#E8F0FE' }) => {
    // ... Icon logic remains the same ...
    const isColored = isActive || isProminent; 
    let iconColor = color;
    let iconBgColor = '#E8F0FE'; 
    
    if (keyName === "dashboard.emergency_info_card") {
        iconColor = '#DC3545';
        iconBgColor = '#FDE9E9';
    } else if (keyName === "medical_menu.access_card_short") {
        iconColor = '#1A73E8';
        iconBgColor = '#E8F0FE';
    } else if (keyName === "dashboard.medical_history_card") {
        iconColor = '#17A2B8';
        iconBgColor = '#E8F7F9';
    }
    
    const baseFontSize = isEasyMode ? 32 : 18;
    let labelFontSize = baseFontSize;

    if (name && name.length > 12) {
        labelFontSize = isEasyMode ? 24 : 16;
    }


    return (
        <div 
            onClick={onClick} 
            style={{
                padding: '25px', 
                margin: '15px',
                border: `5px solid ${isColored ? iconColor : '#e0e0e0'}`,
                borderRadius: '15px', 
                width: '40%',
                textAlign: 'center',
                backgroundColor: isColored ? iconBgColor : '#ffffff',
                filter: isColored ? 'none' : 'grayscale(80%)',
                opacity: isColored ? 1 : 0.7, 
                cursor: 'pointer',
                boxShadow: isColored ? `0 8px 15px ${iconColor}4D` : '0 2px 5px rgba(0, 0, 0, 0.1)',
                transition: 'all 0.3s',
                fontSize: `${labelFontSize}px`, 
            }}
        >
            <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '85px' : '40px', display: 'block', marginBottom: '10px'}}>{emoji}</span>
            <p style={{fontWeight: 'bold', color: '#333', margin: 0}}>{name}</p>
        </div>
    );
};
// --- END Icon Component Modification ---


function Dashboard({ isEasyMode, goToMedical, onMenuClick, goToEmergencyInfo }) { 
    const { t } = useTranslation();
    const [isAlertExpanded, setIsAlertExpanded] = useState(false); // NEW STATE

    const showAppointmentNotification = true; 
    
    const toggleAlert = () => setIsAlertExpanded(prev => !prev); // NEW TOGGLE HANDLER
    
    // NEW STYLE: Transitioned, absolute position, initially off-screen right (translateX(100%))
    const notificationStyle = {
        padding: '15px 25px', 
        paddingLeft: '30px', 
        backgroundColor: '#FFF3CD', 
        color: '#856404', 
        cursor: 'pointer',
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        borderRadius: '10px', // Fully rounded box
        border: '3px solid #FFC107', 
        boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
        zIndex: 90, // Below the Bell and Menu
        
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'flex-start',
        width: 'calc(100% - 30px)', // Take up most of the screen width
        boxSizing: 'border-box',
        
        // ABSOLUTE POSITIONING for slide-out effect
        position: 'absolute',
        top: '10px', 
        right: '15px',
        maxWidth: '400px',
        
        // SLIDE-OUT LOGIC: If expanded, slide to X=0. If not, slide X=100% (hidden)
        transform: isAlertExpanded ? 'translateX(0)' : 'translateX(105%)',
        transition: 'transform 0.4s ease-out',
        pointerEvents: isAlertExpanded ? 'auto' : 'none', // Disable clicks when hidden
    };


    return (
        <div style={{ position: 'relative' }}>
            
            {/* 1. BELL & MENU BUTTONS (Always visible) */}
            <DashboardBellAndMenu 
                onMenuClick={onMenuClick} 
                isEasyMode={isEasyMode} 
                t={t}
                toggleAlert={toggleAlert}
                isAlertExpanded={isAlertExpanded}
            />

            {/* 2. THE SLIDE-OUT NOTIFICATION BANNER (Starts hidden/right) */}
            {showAppointmentNotification && (
                // The Banner text area is now the trigger for navigation
                <div onClick={isAlertExpanded ? goToMedical : undefined} style={notificationStyle}>
                    <div style={{
                        display: 'flex', 
                        alignItems: 'center', 
                        marginBottom: '5px'
                    }}>
                        <span style={{ fontSize: isEasyMode ? '24px' : '16px'}}>
                            {t('dashboard.appointment_soon_alert')}
                        </span>
                    </div>
                    <span style={{ fontSize: isEasyMode ? '32px' : '22px', fontWeight: '900', display: 'block' }}>
                        {t('general.tap_here')}
                    </span>
                </div>
            )}
            {/* END Slide-Out Notification Banner */}


            {/* 3. MAIN ICON GRID (Pushed down to start below the banner area) */}
            <div style={{ 
                display: 'flex', 
                flexWrap: 'wrap', 
                justifyContent: 'center', 
                paddingTop: '100px', // Increased padding to account for the header/bell/menu area
                paddingBottom: '40px' 
            }}>
                
                {/* Icons... (no change) */}
                <Icon 
                    name={t('medical_menu.access_card_short')} 
                    emoji="🏥" 
                    isActive={true} 
                    onClick={goToMedical} 
                    isEasyMode={isEasyMode}
                    keyName={'medical_menu.access_card_short'} 
                />
                
                <Icon 
                    name={t('dashboard.emergency_info_card')} 
                    emoji="🆘" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={goToEmergencyInfo} 
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.emergency_info_card'} 
                />
                
                <Icon 
                    name={t('dashboard.medical_history_card')} 
                    emoji="📜" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={() => console.log('Medical History page route needed.')}
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.medical_history_card'} 
                />
                
                <div style={{ width: '40%', margin: '15px', visibility: 'hidden' }}></div>
            </div>

            {/* CSS Animation for the Bell */}
            <style jsx>{`
                @keyframes blink-bell {
                    0% { 
                        transform: rotate(0deg); 
                        opacity: 1;
                        text-shadow: 0 0 5px #FFC107;
                    }
                    50% { 
                        transform: rotate(10deg); 
                        opacity: 0.8;
                        text-shadow: none;
                    }
                    100% { 
                        transform: rotate(0deg); 
                        opacity: 1;
                        text-shadow: 0 0 5px #FFC107;
                    }
                }
            `}</style>
        </div>
    );
}

export default Dashboard;
